"""Four synchronized original RGB source streams for right-half probes."""

from __future__ import annotations

import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-8, 0, 8), (-12, 0, 0), (1920, 1080), 95),
    "approach": ((1.2, 0, 2), (0, 0, 0), (1280, 720), 90),
    "reference_corner": ((-3, 2.5, 2.6), (-7, 0, 0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0, 0, 0), (1280, 720), 85),
}


class LosslessSourceSink:
    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown right-half source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior right-half camera source")
        width, height = CAMERAS[name][2]
        self.frame_bytes = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed or len(image.raw_data) != self.frame_bytes:
            raise ValueError("Original right-half camera byte count changed")
        self.process.stdin.write(image.raw_data)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Right-half source encoder failed")


class RightHalfCameraCapture:
    def __init__(self, world, carla_module, ego, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named right-half source sinks required")
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.errors = []
        self.sensors = []
        self.closed = False
        try:
            for name, (loc, rot, size, fov) in CAMERAS.items():
                blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
                for key, value in (("image_size_x", size[0]), ("image_size_y", size[1]),
                                   ("fov", fov), ("sensor_tick", 0.05)):
                    blueprint.set_attribute(key, str(value))
                transform = carla_module.Transform(
                    carla_module.Location(*loc), carla_module.Rotation(*rot))
                sensor = world.spawn_actor(blueprint, transform, attach_to=ego)
                self.sensors.append(sensor)
                sensor.listen(lambda image, source=name: self._receive(source, image))
        except BaseException:
            self.close()
            raise

    def _receive(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original right-half camera frame")
                if (image.width, image.height) != CAMERAS[name][2]:
                    raise ValueError("Original right-half camera dimensions changed")
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.errors.append(error)
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, *, timeout_s=10):
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.errors:
                    raise ValueError("Right-half source camera callback failed") from self.errors[0]
                if all(frame in observed for observed in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise ValueError("Missing original right-half source camera frame")
                self.condition.wait(remaining)

    def verify(self, frames):
        expected = set(frames)
        if not expected or any(observed != expected for observed in self.frames.values()):
            raise ValueError("Missing or extra original right-half camera frames")
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in reversed(self.sensors):
                sensor.stop()
                sensor.destroy()

import sys
import unittest
from pathlib import Path
from types import SimpleNamespace as NS

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from right_half_camera import CAMERAS, RightHalfCameraCapture


class Sensor:
    def __init__(self):
        self.callback = None
        self.destroyed = False

    def listen(self, callback):
        self.callback = callback

    def stop(self):
        pass

    def destroy(self):
        self.destroyed = True


class Blueprint:
    def __init__(self):
        self.attributes = {}

    def set_attribute(self, name, value):
        self.attributes[name] = value


class World:
    def __init__(self):
        self.sensors = []

    def get_blueprint_library(self):
        return NS(find=lambda _: Blueprint())

    def spawn_actor(self, blueprint, transform, attach_to):
        sensor = Sensor()
        self.sensors.append(sensor)
        return sensor


class Sink:
    def __init__(self):
        self.frames = []

    def write(self, image):
        self.frames.append(image.frame)


class CameraCaptureTests(unittest.TestCase):
    def test_four_sources_join_and_missing_source_rejected(self):
        world = World()
        carla = NS(Location=lambda *values: values, Rotation=lambda *values: values,
                   Transform=lambda location, rotation: (location, rotation))
        sinks = {name: Sink() for name in CAMERAS}
        cameras = RightHalfCameraCapture(world, carla, object(), sinks)
        self.assertEqual(len(world.sensors), 4)
        for sensor, (name, spec) in zip(world.sensors, CAMERAS.items()):
            width, height = spec[2]
            sensor.callback(NS(frame=20, width=width, height=height))
        cameras.wait_for_frame(20, timeout_s=0.01)
        self.assertEqual(cameras.verify([20]), {name: 1 for name in CAMERAS})
        with self.assertRaisesRegex(ValueError, "Missing or extra"):
            cameras.verify([20, 21])
        world.sensors[0].callback(NS(frame=20, width=1920, height=1080))
        with self.assertRaisesRegex(ValueError, "callback failed"):
            cameras.wait_for_frame(20, timeout_s=0.01)
        cameras.close()
        self.assertTrue(all(sensor.destroyed for sensor in world.sensors))


if __name__ == "__main__":
    unittest.main()

"""Construct a same-direction two-lane roadway with a visible one-way sign actor.

Lane topology and a sign actor are physical candidates. They do not establish
official road designation or sign authority.
"""

from math import hypot


def _unit(waypoint):
    vector=waypoint.transform.get_forward_vector()
    length=hypot(vector.x,vector.y)
    if length<.8:
        raise ValueError('One-way lane tangent unavailable')
    return vector.x/length,vector.y/length


def adjacent_same_direction_left(right_lane):
    left=right_lane.get_left_lane()
    if left is None or left.road_id!=right_lane.road_id:
        raise ValueError('One-way left traffic lane missing')
    if left.lane_width<=0 or right_lane.lane_width<=0 or left.lane_id==right_lane.lane_id:
        raise ValueError('One-way mapped lane widths or identities invalid')
    rx,ry=_unit(right_lane);lx,ly=_unit(left)
    if rx*lx+ry*ly<.95:
        raise ValueError('One-way adjacent lane travels another direction')
    right=(-ry,rx)
    a=right_lane.transform.location;b=left.transform.location
    lateral=(b.x-a.x)*right[0]+(b.y-a.y)*right[1]
    if abs(lateral+(right_lane.lane_width+left.lane_width)/2)>.4:
        raise ValueError('One-way lanes are not joined')
    if right_lane.get_right_lane() is not None or left.get_left_lane() is not None:
        raise ValueError('One-way construction requires two bounded traffic lanes')
    return left


def select_one_way_route(world_map, *, direction='east', minimum_steps=12, step_m=2.5):
    if direction not in ('east','west'):
        raise ValueError('One-way direction unsupported')
    for spawn in world_map.get_spawn_points():
        start=world_map.get_waypoint(spawn.location)
        if start is None or start.is_junction:
            continue
        tx,_=_unit(start)
        if (direction=='east' and tx<=.8) or (direction=='west' and tx>=-.8):
            continue
        try:
            adjacent_same_direction_left(start)
        except ValueError:
            continue
        route=[start]
        for _ in range(minimum_steps):
            options=[w for w in route[-1].next(step_m)
                     if w.road_id==start.road_id and w.lane_id==start.lane_id and
                        not w.is_junction]
            if not options:
                break
            try:
                adjacent_same_direction_left(options[0])
            except ValueError:
                break
            route.append(options[0])
        if len(route)==minimum_steps+1:
            return route
    raise ValueError('No connected bounded same-direction two-lane route')


def one_way_section(right_lane,left_lane):
    selected=adjacent_same_direction_left(right_lane)
    if (selected.road_id,selected.lane_id)!=(left_lane.road_id,left_lane.lane_id):
        raise ValueError('One-way original lane pair differs')
    tx,ty=_unit(right_lane);lx,ly=_unit(left_lane);right=(-ty,tx)
    a=right_lane.transform.location;b=left_lane.transform.location
    right_edge=[a.x+right[0]*right_lane.lane_width/2,
                a.y+right[1]*right_lane.lane_width/2]
    left_edge=[b.x-right[0]*left_lane.lane_width/2,
               b.y-right[1]*left_lane.lane_width/2]
    center=[(right_edge[i]+left_edge[i])/2 for i in (0,1)]
    return {'roadway_center_point_xy':center,'travel_tangent_xy':[tx,ty],
            'left_lane_tangent_xy':[lx,ly],
            'left_road_edge_xy':left_edge,'right_road_edge_xy':right_edge,
            'right_lane_id':right_lane.lane_id,'left_lane_id':left_lane.lane_id,
            'road_id':right_lane.road_id,'right_lane_width_m':float(right_lane.lane_width),
            'left_lane_width_m':float(left_lane.lane_width)}


def spawn_one_way_sign(world, carla, waypoint):
    library=world.get_blueprint_library()
    blueprints=list(library.filter('*oneway*'))+list(library.filter('*one_way*'))
    unique={bp.id:bp for bp in blueprints}
    if not unique:
        raise ValueError('Native one-way sign blueprint unavailable')
    blueprint=unique[sorted(unique)[0]]
    tx,ty=_unit(waypoint);right=(-ty,tx)
    source=waypoint.transform.location
    transform=carla.Transform(carla.Location(
        x=source.x+tx*5+right[0]*(waypoint.lane_width/2+.5),
        y=source.y+ty*5+right[1]*(waypoint.lane_width/2+.5),
        z=source.z+.1),waypoint.transform.rotation)
    actor=world.try_spawn_actor(blueprint,transform)
    if actor is None:
        raise ValueError('Native one-way sign spawn failed')
    return actor

"""Saved-only original one-way lane, body and sign measurement."""

import json
from hashlib import sha256
from math import hypot
from pathlib import Path


def _rows(root,name):
    path=Path(root)/name
    if not path.is_file() or not path.read_bytes():
        raise ValueError('Missing required source: '+name)
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def measure_one_way(root):
    root=Path(root)
    roadway=_rows(root,'one_way_roadway.jsonl')
    signs=_rows(root,'one_way_sign.jsonl')
    frames=_rows(root,'video_frames.jsonl')
    trace=_rows(root,'trace.jsonl')
    if not roadway or not len(roadway)==len(signs)==len(frames)==len(trace):
        raise ValueError('One-way original source lengths differ')
    sign_id=None;ego_id=None;observations=[];initial_sign=None
    for index,(road,sign,frame,motion) in enumerate(zip(roadway,signs,frames,trace)):
        f,t=frame.get('carla_frame'),frame.get('time_s')
        if frame.get('video_frame')!=index or any(row.get('frame')!=f or row.get('time_s')!=t
                for row in (road,sign,motion)):
            raise ValueError('One-way original frame/time join differs')
        if index and (f!=frames[index-1]['carla_frame']+1 or
                      abs(t-frames[index-1]['time_s']-.05)>1e-4):
            raise ValueError('One-way source not continuous at 20 Hz')
        if sign.get('designation_verified') is not False or sign.get('posting_authority_verified') is not False:
            raise ValueError('One-way source claims unsupported authority')
        if 'oneway' not in sign.get('blueprint_id','').lower().replace('_',''):
            raise ValueError('One-way sign original type differs')
        if sign_id is None:sign_id=sign.get('actor_id')
        if ego_id is None:ego_id=road.get('ego_id')
        if not sign_id or not ego_id or sign.get('actor_id')!=sign_id or road.get('ego_id')!=ego_id:
            raise ValueError('One-way original actor identity changed')
        point=sign['position_m']
        if initial_sign is None:initial_sign=point
        if len(point)!=3 or sum((a-b)**2 for a,b in zip(point,initial_sign))>.01:
            raise ValueError('One-way sign moved from original placement')
        tangent=road['travel_tangent_xy'];left_tangent=road['left_lane_tangent_xy']
        if not .99<=hypot(*tangent)<=1.01 or not .99<=hypot(*left_tangent)<=1.01 or sum(
                tangent[i]*left_tangent[i] for i in (0,1))<.95:
            raise ValueError('One-way original lanes are not same-direction')
        right=(-tangent[1],tangent[0]);center=road['roadway_center_point_xy']
        def offset(point):return sum((point[i]-center[i])*right[i] for i in (0,1))
        left_edge=offset(road['left_road_edge_xy']);right_edge=offset(road['right_road_edge_xy'])
        corners=road['ego_corners']
        if not left_edge<0<right_edge or len(corners)!=4 or any(
                not left_edge<=offset(corner)<=right_edge for corner in corners):
            raise ValueError('One-way original road/body geometry invalid')
        if offset(point)<=right_edge:
            raise ValueError('One-way sign is not placed at right roadside')
        observations.append({'frame':f,'time_s':t,'minimum_body_right_offset_m':min(map(offset,corners)),
                             'roadway_width_m':right_edge-left_edge,
                             'sign_lateral_offset_m':offset(point)})
    return {'observations':observations,'sign_actor_id':sign_id,'subject_actor_id':ego_id,
            'minimum_body_right_offset_m':min(o['minimum_body_right_offset_m'] for o in observations),
            'designation_verified':False,'posting_authority_verified':False,
            'sources':{name:sha256((root/name).read_bytes()).hexdigest() for name in (
                'one_way_roadway.jsonl','one_way_sign.jsonl','video_frames.jsonl','trace.jsonl')}}
